package wgmodern;
import java.util.*;import net.minecraft.core.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.effect.*;import net.minecraft.world.item.*;import net.minecraft.world.item.enchantment.EnchantmentHelper;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.phys.*;import net.minecraft.tags.*;import net.minecraft.sounds.*;import tc4revival.content.*;import tc4revival.aspect.TCAspects;
public class InfusedGem extends Item {
 public InfusedGem(){super(new Properties());}
 public static ItemStack create(String aspect,int cut){var s=new ItemStack(Content.INFUSED_GEM.get());s.getOrCreateTag().putString("Aspect",aspect);s.getOrCreateTag().putByte("GemCut",(byte)Math.floorMod(cut,2));return s;}
 public static int cut(ItemStack s){return s.hasTag()?Math.floorMod(s.getTag().getByte("GemCut"),2):0;}
 public static String aspect(ItemStack s){return s.hasTag()?s.getTag().getString("Aspect"):"";}
 public static int color(ItemStack s){var a=thaumcraft.api.aspects.Aspect.getAspect(aspect(s));return a==null?0xffffff:a.getColor();}
 @Override public int getMaxStackSize(ItemStack s){return cut(s)==0?64:1;}@Override public int getMaxDamage(ItemStack s){return 32;}
 /** Forge's default checks the fixed Item properties, ignoring our per-stack charge capacity. */
 @Override public boolean isDamageable(ItemStack s){return getMaxDamage(s)>0;}
 @Override public boolean isBarVisible(ItemStack s){return s.getDamageValue()>0;}@Override public int getBarWidth(ItemStack s){return Math.round(13*(1-s.getDamageValue()/32f));}
 @Override public String getDescriptionId(ItemStack s){return "item.WG_InfusedGem"+(aspect(s).isEmpty()?".innert":"");}
 @Override public Component getName(ItemStack s){var a=thaumcraft.api.aspects.Aspect.getAspect(aspect(s));return a==null?super.getName(s):super.getName(s).copy().append(" ("+a.getName()+")");}
 @Override public void appendHoverText(ItemStack s,Level l,List<Component> lines,TooltipFlag f){lines.add(Component.translatable("wg.desc.gemcut."+(cut(s)==0?"POINT":"OVAL")));}
 @Override public InteractionResult onItemUseFirst(ItemStack stack,net.minecraft.world.item.context.UseOnContext context){
  if(context.getPlayer()==null||cut(stack)!=1||!aspect(stack).equals("perditio"))return InteractionResult.PASS;
  var target=context.getLevel().getBlockEntity(context.getClickedPos());
  if(!(target instanceof ItemMirrorBlockEntity)&&!(target instanceof EssentiaMirrorBlockEntity))return InteractionResult.PASS;
  // Mirrors consume normal block interaction; the legacy gem activates without sneaking.
  return use(context.getLevel(),context.getPlayer(),context.getHand()).getResult();
 }
 @Override public InteractionResultHolder<ItemStack> use(Level l,Player p,InteractionHand hand){var s=p.getItemInHand(hand);if(l.isClientSide)return InteractionResultHolder.success(s);int brittle=EnchantmentHelper.getItemEnchantmentLevel(WGMagic.ENCHANTS.get("gemstone_brittle").get(),s);if(brittle>=3||l.random.nextInt(20)<brittle){shatter(p,s,true);return InteractionResultHolder.consume(s);}int cut=cut(s),cost=GemRules.charge(aspect(s),tc4revival.config.TCConfig.SERVER.allowMirrors.get());if(cut==1&&s.getDamageValue()+cost>32)return InteractionResultHolder.fail(s);int potency=EnchantmentHelper.getItemEnchantmentLevel(WGMagic.ENCHANTS.get("gemstone_potency").get(),s);if(!effect(p,aspect(s),cut,potency))return InteractionResultHolder.pass(s);if(cut==0)shatter(p,s,false);else if(!p.isCreative())s.setDamageValue(s.getDamageValue()+cost);return InteractionResultHolder.consume(s);}
 private static void shatter(Player p,ItemStack gem,boolean message){gem.shrink(1);var dust=new ItemStack(Content.MATERIALS.get("gemstone_dust").get());if(!p.getInventory().add(dust))p.drop(dust,false);if(message)p.displayClientMessage(Component.translatable("wg.chat.gem.shatter"),false);}
 @Override public void inventoryTick(ItemStack s,Level l,Entity e,int slot,boolean selected){if(l.isClientSide||!(e instanceof Player p))return;int brittle=EnchantmentHelper.getItemEnchantmentLevel(WGMagic.ENCHANTS.get("gemstone_brittle").get(),s);if(l.random.nextInt(1000)<brittle||(cut(s)==0&&s.getDamageValue()>0)){shatter(p,s,true);return;}if(l.random.nextInt(20)<brittle)return;if(selected&&cut(s)==1&&s.getDamageValue()>0&&p.tickCount%4==0){var a=TCAspects.catalog().find(aspect(s)).orElse(null);var relay=VisRelayBlockEntity.nearby(p);if(a!=null&&relay!=null&&relay.consumeVis(a,1)>0){s.setDamageValue(s.getDamageValue()-1);WGNetwork.gemEffect((ServerPlayer)p,2,relay.getBlockPos(),a.color());}}}
 public static boolean effect(Player p,String aspect,int cut,int potency){if(!GemRules.PRIMALS.contains(aspect)||!(p instanceof ServerPlayer player))return false;var l=player.serverLevel();var origin=BlockPos.containing(p.getX(),(int)p.getY()+1,p.getZ());
 if(cut==0){switch(aspect){case "aer"->p.addEffect(new MobEffectInstance(MobEffects.JUMP,300+20*potency,4+(potency>1?1:0)));case "ignis"->{int[] offsets=potency<=0?new int[]{-2,2}:potency==1?new int[]{-4,4}:potency==2?new int[]{-6,-4,4,6}:new int[]{-8,-6,-4,4,6,8};for(int x:offsets)for(int z:offsets)light(l,origin.offset(x,0,z),3600+800*potency,p);light(l,origin.above(2),3600+800*potency,p);}case "aqua"->{int radius=2+potency;for(var pos:BlockPos.betweenClosed(origin.offset(-radius,-3,-radius),origin.offset(radius,0,radius))){if(!l.hasChunkAt(pos)||!l.mayInteract(p,pos))continue;var f=l.getFluidState(pos);if(f.is(FluidTags.WATER))l.setBlockAndUpdate(pos,Blocks.ICE.defaultBlockState());else if(f.is(FluidTags.LAVA))l.setBlockAndUpdate(pos,(f.isSource()?Blocks.OBSIDIAN:Blocks.COBBLESTONE).defaultBlockState());}}case "terra"->p.addEffect(new MobEffectInstance(WGMagic.KNOCKBACK.get(),100+100*potency,1+(potency>0?1:0)));case "ordo"->p.heal(6+6*potency);case "perditio"->thaumcraft.api.ThaumcraftApiHelper.addWarpToPlayer(player,3+3*potency,true);}return true;}
 var hit=getPlayerPOVHitResult(l,p,ClipContext.Fluid.NONE);var target=hit.getBlockPos().relative(hit.getDirection());boolean hitBlock=hit.getType()==HitResult.Type.BLOCK;
 switch(aspect){case "aer"->{p.push(p.getLookAngle().x*(1+potency),p.getLookAngle().y*(1+potency),p.getLookAngle().z*(1+potency));p.fallDistance=0;p.hurtMarked=true;return true;}
 case "ignis"->{if(hitBlock&&l.isEmptyBlock(target)&&l.mayInteract(p,target)){l.setBlockAndUpdate(target,BaseFireBlock.getState(l,target));l.playSound(null,target,SoundEvents.FIRECHARGE_USE,SoundSource.PLAYERS,1,.8f+l.random.nextFloat()*.4f);return true;}}
 case "aqua"->{if(hitBlock&&l.getBlockState(target).canBeReplaced()&&l.mayInteract(p,target)){if(l.dimensionType().ultraWarm()){l.playSound(null,target,SoundEvents.FIRE_EXTINGUISH,SoundSource.PLAYERS,1,.8f+l.random.nextFloat()*.4f);l.sendParticles(net.minecraft.core.particles.ParticleTypes.LARGE_SMOKE,target.getX()+.5,target.getY()+.5,target.getZ()+.5,8,.5,.5,.5,0);}else l.setBlockAndUpdate(target,Blocks.WATER.defaultBlockState());return true;}}
 case "terra"->{if(hitBlock){for(var ore:ores(l,hit.getBlockPos()))WGNetwork.gemEffect(player,0,ore,0x668c0d);return true;}}
 case "ordo"->{var node=WGLoadedChunks.nearest(l,origin);if(node!=null){var to=Vec3.atCenterOf(node.getBlockPos()).subtract(p.getEyePosition());float yaw=(float)(Math.toDegrees(Math.atan2(to.z,to.x))-90),pitch=(float)-Math.toDegrees(Math.atan2(to.y,to.horizontalDistance()));player.connection.teleport(player.getX(),player.getY(),player.getZ(),yaw,pitch);int color=0xffffff;for(var a:node.aspects().aspects())color=blend(color,a.color());WGNetwork.gemEffect(player,1,node.getBlockPos(),color);return true;}}
 case "perditio"->{if(!tc4revival.config.TCConfig.SERVER.allowMirrors.get()){for(var other:l.getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(4,2,4)))if(other!=p){other.push((other.getX()-p.getX())*.4,.4,(other.getZ()-p.getZ())*.4);other.addEffect(new MobEffectInstance(MobEffects.BLINDNESS,15));}return true;}if(hitBlock){var be=l.getBlockEntity(target);if(!(be instanceof ItemMirrorBlockEntity)&&!(be instanceof EssentiaMirrorBlockEntity))be=l.getBlockEntity(hit.getBlockPos());GlobalPos destination=null;if(be instanceof ItemMirrorBlockEntity mirror&&mirror.valid(true))destination=mirror.destination();else if(be instanceof EssentiaMirrorBlockEntity mirror&&mirror.valid(true))destination=mirror.mirrorDestination();if(destination!=null){var world=l.getServer().getLevel(destination.dimension());if(world==null)return false;var other=world.getBlockEntity(destination.pos());Direction face=other instanceof ItemMirrorBlockEntity m?m.facing():other instanceof EssentiaMirrorBlockEntity m?m.facing():null;if(face==null)return false;var pos=destination.pos();player.teleportTo(world,pos.getX()+.5+face.getStepX()*.5,pos.getY()+face.getStepY(),pos.getZ()+.5+face.getStepZ()*.5,face.get2DDataValue()<0?0:face.toYRot(),p.getXRot());return true;}}}
 }return false;}
 private static int blend(int a,int b){return (((a>>16&255)+(b>>16&255))/2<<16)|(((a>>8&255)+(b>>8&255))/2<<8)|((a&255)+(b&255))/2;}
 private static void light(Level l,BlockPos pos,int duration,Player p){if(l.hasChunkAt(pos)&&l.isEmptyBlock(pos)&&l.getMaxLocalRawBrightness(pos)<10&&l.mayInteract(p,pos)){l.setBlockAndUpdate(pos,Content.LIGHT.get().defaultBlockState());if(l.getBlockEntity(pos) instanceof TemporaryLight.Tile tile){tile.remaining=duration;tile.setChanged();}}}
 public static List<BlockPos> ores(Level level,BlockPos origin){var result=new ArrayList<BlockPos>();var open=new ArrayDeque<BlockPos>();var seen=new HashSet<BlockPos>();var start=level.getBlockState(origin).getBlock();open.add(origin);seen.add(origin);int checked=0;while(!open.isEmpty()&&checked++<400){var pos=open.remove();if(level.getBlockState(pos).is(net.minecraftforge.common.Tags.Blocks.ORES))result.add(pos);for(var dir:Direction.values()){var next=pos.relative(dir);if(next.distSqr(origin)>=32||!level.hasChunkAt(next)||seen.contains(next))continue;var state=level.getBlockState(next);if(state.is(start)||state.is(net.minecraftforge.common.Tags.Blocks.ORES)){seen.add(next);open.add(next);}}}return result;}
}
